/bin/bash -lc "node <<'JS'
const { chromium } = require('/tmp/claude-0/-root-design/f13cfb4d-b71e-4ed8-960a-ee0a8c2a8818/scratchpad/pwnode/node_modules/playwright-core');
const fs = require('fs');
(async () => {
 const browser = await chromium.launch({headless: true, args: ['--no-sandbox', '--no-zygote', '--single-process']});
 const page = await browser.newPage({viewport: {width: 240, height: 180}, deviceScaleFactor: 2});
 await page.setContent('<style>body{margin:0}</style>' + fs.readFileSync('caught-up.svg', 'utf8'));
 const result = await page.evaluate(() => {
  const el = document.querySelector('.caught-up-envelope');
  const a = el.getAnimations()[0];
  a.pause();
  const offsets = [0, 3500, 7000].map(t => { a.currentTime = t; return new DOMMatrix(getComputedStyle(el).transform).m42; });
  if (offsets.join(',') "'!== '"'0,-3,0') throw Error('Unexpected motion: ' + offsets);
  a.currentTime = 0;
  return offsets;
 });
 await page.screenshot({path: '/tmp/caught-up-preview.png'});
 await page.emulateMedia({reducedMotion: 'reduce'});
 const count = await page.locator('.caught-up-envelope').evaluate(el => el.getAnimations().length);
 if (count "'!== 0) throw Error('"'Reduced motion still animated');
 console.log('Browser verified: seamless motion offsets ' + result + '; reduced motion disables animation.');
 await browser.close();
})();
JS"

